{
  "families": [
    {
      "family": "pipelined",
      "ranges": [
        {"param": "data_width", "low": 12, "high": 20, "choices": null},
        {"param": "n_iter", "low": 10, "high": 20, "choices": null},
        {"param": "angle_guard", "low": 0, "high": 4, "choices": null},
        {"param": "frac_guard", "low": 0, "high": 4, "choices": null},
        {"param": "rounding", "low": null, "high": null, "choices": ["trunc", "round"]}
      ],
      "budget_share": 65,
      "why": "One registered stage per micro-rotation gives the shortest combinational path and therefore the highest Fmax, the only realistic way to reach 400 MSPS single-lane. Widths and iteration counts span the 12-bit accuracy threshold so the search can find the minimum-LUT feasible corner."
    },
    {
      "family": "pipelined_m",
      "ranges": [
        {"param": "data_width", "low": 12, "high": 20, "choices": null},
        {"param": "n_iter", "low": 10, "high": 20, "choices": null},
        {"param": "angle_guard", "low": 0, "high": 4, "choices": null},
        {"param": "frac_guard", "low": 0, "high": 4, "choices": null},
        {"param": "rounding", "low": null, "high": null, "choices": ["trunc", "round"]},
        {"param": "m", "low": 2, "high": 3, "choices": null}
      ],
      "budget_share": 35,
      "why": "Still 1 result/cycle, but registering every 2-3 stages cuts pipeline FF count and may reduce the area proxy; m is kept small because larger m lengthens the combinational path and risks dropping below 400 MSPS. Check whether it yields lower LUTs than fully pipelined at the same accuracy."
    }
  ],
  "rationale": "The 400 MSPS single-lane constraint rules out iterative (N+3 cycles/result) and unrolled_k (ceil(N/k)+3 >= 4 cycles/result), which would need Fmax >= 1600 MHz on Artix-7. Only pipelined and pipelined_m produce one result per cycle, so the first round concentrates on those two families. Ranges for data_width and n_iter bracket the 2^-12 error limit (output LSB 2^-(W-2) and CORDIC angle error ~2^-N), while angle_guard/frac_guard/rounding let the search trade extra internal bits for accuracy without inflating the output width. The budget is split toward fully pipelined because it has the best chance of meeting the throughput constraint; pipelined_m gets a smaller share to test whether fewer pipeline registers lower LUTs while still hitting 400 MSPS."
}
